def extend_python(course):
    for raw_n,title,body,why,tryit,mistake,level in PYTHON_EXPANSION:
        course.append({"n":int(raw_n),"title":title,"part":"Part 6 — Intermediate & Production Python",
                     "body":f"{title}\nIn Plain English\n{body}\n\nWhy This Matters\n{why}\n\nTry It Yourself\n{tryit}\n\nCommon Mistake\n{mistake}\n\nLevel Up\n{level}"})
    return course
